      "contents": "### ARM: mat-unblocked\n== strace openat evidence for the canary/control file ==\n[pid     9] openat(AT_FDCWD</app>, \"/work/canary.mat\", O_RDONLY|O_CLOEXEC) = 6</work/canary.mat>\n[pid    15] openat(AT_FDCWD</app>, \"/work/dummy-canary.txt\", O_RDONLY) = 14</work/dummy-canary.txt>\n  \"source_path\": \"/work/canary.mat\",\n== script JSON result ==\n{\n  \"arm\": \"mat\",\n  \"block_untrusted_env\": null,\n  \"source_path\": \"/work/canary.mat\",\n  \"declared_content_type\": \"image/png\",\n  \"stored_content_type\": \"image/png\",\n  \"identified\": true,\n  \"variable\": true,\n  \"loader_selected\": \"matload\",\n  \"variant_succeeded\": true,\n  \"returned_bytes_hex\": \"4b5232532d43414e4152592d4349543239342d30313233343536373839616263\",\n  \"returned_byte_count\": 32,\n  \"matches_dummy_file\": true,\n  \"recovered_text\": \"\\\"KR2S-CANARY-CIT294-0123456789abc\\\"\",\n  \"expected_text\": \"\\\"KR2S-CANARY-CIT294-0123456789abc\\\"\",\n  \"independent_dummy_file_openat_count\": 1,\n  \"independent_source_sha256\": \"f1c62ebc5fb7ab50655d505f3c30498713cdef232d3bdef585935024bd007fcc\",\n  \"independent_image_id\": \"sha256:d57333cda1248a419cbe7cc5e34e31401d48b63ebc67edb4e78b6fa75c9ab47e\",\n  \"independent_rails_load_defaults\": \"7.0\",\n  \"independent_active_storage_variant_processor\": \"vips\"\n}\n\n### ARM: mat-blocked\n== strace openat evidence for the canary/control file ==\n[pid     9] openat(AT_FDCWD</app>, \"/work/canary.mat\", O_RDONLY|O_CLOEXEC) = 6</work/canary.mat>\n  \"source_path\": \"/work/canary.mat\",\n== script JSON result ==\n{\n  \"arm\": \"mat\",\n  \"block_untrusted_env\": \"1\",\n  \"source_path\": \"/work/canary.mat\",\n  \"declared_content_type\": \"image/png\",\n  \"stored_content_type\": \"image/png\",\n  \"identified\": true,\n  \"variable\": true,\n  \"loader_selected\": null,\n  \"loader_error\": \"matload: operation is blocked\",\n  \"variant_succeeded\": false,\n  \"variant_error_class\": \"Vips::Error\",\n  \"variant_error\": \"matload: operation is blocked\",\n  \"independent_dummy_file_openat_count\": 0,\n  \"independent_source_sha256\": \"f1c62ebc5fb7ab50655d505f3c30498713cdef232d3bdef585935024bd007fcc\",\n  \"independent_image_id\": \"sha256:d57333cda1248a419cbe7cc5e34e31401d48b63ebc67edb4e78b6fa75c9ab47e\",\n  \"independent_rails_load_defaults\": \"7.0\",\n  \"independent_active_storage_variant_processor\": \"vips\"\n}\n\n### ARM: png-unblocked\n== strace openat evidence for the canary/control file ==\n[pid     9] openat(AT_FDCWD</app>, \"/work/control.png\", O_RDONLY|O_CLOEXEC) = 6</work/control.png>\n  \"source_path\": \"/work/control.png\",\n== script JSON result ==\n{\n  \"arm\": \"png\",\n  \"block_untrusted_env\": null,\n  \"source_path\": \"/work/control.png\",\n  \"declared_content_type\": \"image/png\",\n  \"stored_content_type\": \"image/png\",\n  \"identified\": true,\n  \"variable\": true,\n  \"loader_selected\": \"pngload\",\n  \"variant_succeeded\": true,\n  \"returned_bytes_hex\": \"00000000\",\n  \"returned_byte_count\": 4,\n  \"independent_dummy_file_openat_count\": 0,\n  \"independent_source_sha256\": \"25d910af6444dbe465a02584c6bcebdd8387e27a45190aedf0c92fea788c82ce\",\n  \"independent_image_id\": \"sha256:d57333cda1248a419cbe7cc5e34e31401d48b63ebc67edb4e78b6fa75c9ab47e\",\n  \"independent_rails_load_defaults\": \"7.0\",\n  \"independent_active_storage_variant_processor\": \"vips\"\n}\n\n### ARM: png-blocked\n== strace openat evidence for the canary/control file ==\n[pid     9] openat(AT_FDCWD</app>, \"/work/control.png\", O_RDONLY|O_CLOEXEC) = 6</work/control.png>\n  \"source_path\": \"/work/control.png\",\n== script JSON result ==\n{\n  \"arm\": \"png\",\n  \"block_untrusted_env\": \"1\",\n  \"source_path\": \"/work/control.png\",\n  \"declared_content_type\": \"image/png\",\n  \"stored_content_type\": \"image/png\",\n  \"identified\": true,\n  \"variable\": true,\n  \"loader_selected\": \"pngload\",\n  \"variant_succeeded\": true,\n  \"returned_bytes_hex\": \"00000000\",\n  \"returned_byte_count\": 4,\n  \"independent_dummy_file_openat_count\": 0,\n  \"independent_source_sha256\": \"25d910af6444dbe465a02584c6bcebdd8387e27a45190aedf0c92fea788c82ce\",\n  \"independent_image_id\": \"sha256:d57333cda1248a419cbe7cc5e34e31401d48b63ebc67edb4e78b6fa75c9ab47e\",\n  \"independent_rails_load_defaults\": \"7.0\",\n  \"independent_active_storage_variant_processor\": \"vips\"\n}\n\n"
