      "contents": "examples {\n  [\"mat-unblocked\"] {\n    \"matload\"\n    true\n    #\"\"KR2S-CANARY-CIT294-0123456789abc\"\"#\n    1\n  }\n  [\"mat-blocked\"] {\n    null\n    false\n    \"Vips::Error\"\n    \"matload: operation is blocked\"\n    0\n  }\n  [\"png-unblocked\"] {\n    \"pngload\"\n    true\n    \"00000000\"\n  }\n  [\"png-blocked\"] {\n    \"pngload\"\n    true\n    \"00000000\"\n  }\n}\n"
